/* A fully English diagram per strategy; replaces Arabic words embedded in SVGs. */
(function(){if(window.BOUSALA_LANG!=='en')return;let n=0;const V=window.AL101_VISUALS;if(!V)return;
V.diagram=function(s){const p=V.category(s),c=p.color,light=p.light;const steps=(s.steps||[]).slice(0,4);const e=V.esc||((x)=>String(x));const id='bousla-en-'+(n++);const w=steps.length===3?164:122;const gap=14;const start=(580-(steps.length*w+(steps.length-1)*gap))/2;
const body=steps.map((it,i)=>{const x=start+i*(w+gap),label=String(it[0]||'Step').split(' ').slice(0,4).join(' ');const words=label.split(' ');const a=words.slice(0,2).join(' '),b=words.slice(2).join(' ');return `<rect x="${x}" y="78" width="${w}" height="109" rx="17" fill="${i%2?light:'#fff'}" stroke="${c}" stroke-width="2"/><circle cx="${x+w/2}" cy="98" r="14" fill="${c}"/><text x="${x+w/2}" y="103" font-size="12" text-anchor="middle" fill="white" font-weight="700">${i+1}</text><text x="${x+w/2}" y="139" font-size="12.5" font-weight="700" fill="#234556" text-anchor="middle">${e(a)}</text><text x="${x+w/2}" y="157" font-size="12.5" fill="#234556" text-anchor="middle">${e(b)}</text>${i<steps.length-1?`<path d="M${x+w+2} 132 l${gap-4} 0 l-5 -4 m5 4 l-5 4" fill="none" stroke="${c}" stroke-width="1.8"/>`:''}`}).join('');
return `<svg xmlns="http://www.w3.org/2000/svg" class="strategy-diagram" viewBox="0 0 580 278" role="img" aria-label="Step-by-step diagram for ${e(s.name)}"><rect x="1" y="1" width="578" height="276" rx="22" fill="#fbfdff" stroke="#d6e2e9"/><rect x="15" y="12" width="254" height="28" rx="14" fill="${light}"/><text x="142" y="31" font-size="13" font-weight="700" fill="${c}" text-anchor="middle">${e(p.label)}</text>${body}<text x="290" y="228" text-anchor="middle" font-size="14" fill="#234556">${e(s.name)}</text></svg>`;
};})();